#!/usr/bin/env python3
"""Filter and aggregate RFC-4180-style CSV files."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import OrderedDict
from decimal import Decimal, InvalidOperation
from pathlib import Path


def parse_filter(value: str) -> tuple[str, str]:
    if "=" not in value:
        raise argparse.ArgumentTypeError("filters must use COLUMN=VALUE")
    column, expected = value.split("=", 1)
    if not column:
        raise argparse.ArgumentTypeError("filter column must not be empty")
    return column, expected


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", help="input CSV file")
    parser.add_argument("--where", action="append", default=[], type=parse_filter,
                        metavar="COLUMN=VALUE", help="keep rows matching a column value")
    parser.add_argument("--group-by", metavar="COLUMN", help="column used to group aggregates")
    parser.add_argument("--sum", dest="sum_column", metavar="COLUMN", help="numeric column to sum")
    parser.add_argument("--avg", dest="avg_column", metavar="COLUMN", help="numeric column to average")
    parser.add_argument("--output", choices=("json", "csv"), default="json", help="output format")
    args = parser.parse_args(argv)
    if (args.sum_column or args.avg_column) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    return args


def read_csv(filename: str) -> tuple[list[str], list[dict[str, str]]]:
    try:
        with Path(filename).open("r", encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source)
            try:
                headers = next(reader)
            except StopIteration:
                raise ValueError("input CSV is empty")

            if not headers or any(not header for header in headers):
                raise ValueError("CSV headers must be non-empty")
            duplicates = sorted({header for header in headers if headers.count(header) > 1})
            if duplicates:
                raise ValueError(f"CSV headers must be unique: {', '.join(duplicates)}")

            rows = []
            for row_number, values in enumerate(reader, start=2):
                if len(values) != len(headers):
                    raise ValueError(
                        f"row {row_number} has {len(values)} fields; expected {len(headers)}"
                    )
                rows.append(dict(zip(headers, values)))
            return headers, rows
    except OSError as exc:
        raise ValueError(f"cannot read input file: {exc}") from exc
    except csv.Error as exc:
        raise ValueError(f"malformed CSV: {exc}") from exc


def require_columns(headers: list[str], columns: list[str | None]) -> None:
    unknown = [column for column in columns if column is not None and column not in headers]
    if unknown:
        raise ValueError(f"unknown column: {unknown[0]}")


def decimal_text(value: Decimal) -> str:
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return "0" if text in ("", "-0") else text


def aggregate(rows: list[dict[str, str]], args: argparse.Namespace) -> tuple[list[str], list[dict[str, str]]]:
    groups: OrderedDict[str, dict[str, Decimal | int]] = OrderedDict()
    for index, row in enumerate(rows, start=2):
        group = row[args.group_by]
        values = groups.setdefault(group, {"count": 0})
        values["count"] += 1
        for kind, column in (("sum", args.sum_column), ("avg", args.avg_column)):
            if column is None:
                continue
            cell = row[column]
            try:
                number = Decimal(cell)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid numeric value at row {index}, column {column}: {cell!r}")
            if not number.is_finite():
                raise ValueError(f"invalid numeric value at row {index}, column {column}: {cell!r}")
            key = f"{kind}_total"
            values[key] = values.get(key, Decimal(0)) + number

    output_headers = [args.group_by]
    if args.sum_column:
        output_headers.append(f"sum_{args.sum_column}")
    if args.avg_column:
        output_headers.append(f"avg_{args.avg_column}")
    output_rows = []
    for group in sorted(groups):
        values = groups[group]
        result = {args.group_by: group}
        if args.sum_column:
            result[f"sum_{args.sum_column}"] = decimal_text(values["sum_total"])
        if args.avg_column:
            result[f"avg_{args.avg_column}"] = decimal_text(values["avg_total"] / values["count"])
        output_rows.append(result)
    return output_headers, output_rows


def write_output(headers: list[str], rows: list[dict[str, str]], output: str) -> None:
    if output == "json":
        json.dump(rows, sys.stdout, ensure_ascii=False)
        sys.stdout.write("\n")
        return
    writer = csv.DictWriter(sys.stdout, fieldnames=headers, lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)


def main(argv: list[str] | None = None) -> int:
    try:
        args = parse_args(sys.argv[1:] if argv is None else argv)
        headers, rows = read_csv(args.input)
        require_columns(headers, [column for column, _ in args.where] + [args.group_by, args.sum_column, args.avg_column])
        filtered = [row for row in rows if all(row[column] == expected for column, expected in args.where)]
        if args.group_by:
            headers, filtered = aggregate(filtered, args)
        write_output(headers, filtered, args.output)
        return 0
    except (ValueError, argparse.ArgumentError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
